let cur = null;
for (let line of lines) {
  if (line.startsWith("# Page: ")) {
    if (cur) pages.push(cur);
    cur = {title: line.slice(8).trim(), lines: []};
  } else if (cur) {
    cur.lines.push(line);
  }
