if (cur) pages.push(cur);

function countCodeBlocks(pageLines) {
  let count = 0;
  let i = 0;
  while (i < pageLines.length) {
    let l = pageLines[i];
    if (l.trim().startsWith("```")) {
      let fence = l.trim();
      let lang = fence.slice(3).trim().toLowerCase();
      // find closing
      let j = i+1;
      while (j < pageLines.length && !pageLines[j].trim().startsWith("```")) j++;
      if (lang !== "mermaid") count++;
      i = j+1;
    } else {
      i++;
    }
  }
  return count;
}

let results = pages.map(p => ({title: p.title, count: countCodeBlocks(p.lines)}));
results.sort((a,b)=>b.count-a.count);
let top = results.slice(0,5);

let topPage = pages.find(p => p.title === top[0].title);
let firstH2 = topPage.lines.find(l => l.startsWith("## "));

return JSON.stringify({top, firstH2}, null, 2);

